\section{Threat Model and Problem Formulation}
\label{sec:threat_model}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/fig_keff_eta_scatter_main.pdf}
\caption{$K_{\mathrm{eff}}$--$\eta_{\max}$ scatter at $K{=}3$ (455 panels). The $r{=}0.70$ correlation reflects structural coupling between diversity and capability in the current LLM ecosystem.}
\label{fig:keff_eta_scatter_main}
\end{figure}

\begin{table}[t]
\centering
\small
\resizebox{\columnwidth}{!}{%
\begin{tabular}{llll}
\toprule
\textbf{Attack} & \textbf{Category} & \textbf{Mechanism} & \textbf{Target} \\
\midrule
Prompt inj.    & Targeted    & Override instruct. & Decision \\
Score manip.   & Targeted    & Numeric anchoring  & Score \\
Sycophancy     & Shared bias & Flattery/agreement & Preference \\
Verbosity      & Shared bias & Content padding    & Attention \\
Position bias  & Shared bias & Response reorder   & Position \\
Authority bias & Shared bias & Credential appeal  & Trust \\
\bottomrule
\end{tabular}}
\caption{Attack taxonomy. Targeted attacks exploit individual judge weaknesses; shared-bias attacks affect most judges similarly (\S\ref{sec:experiments}).}
\label{tab:attack_taxonomy}
\end{table}

A \emph{panel} $\mathcal{P} = \{J_1, \ldots, J_K\}$ consists of $K$ judges (with $K$ odd) that evaluate a candidate text via majority vote: the text is accepted if at least $t = \lceil K/2 \rceil$ judges approve it. Under an attack $a$, each judge $J_j$ is compromised with marginal failure probability $\eta_j(a) = \Pr(X_j^a = 1)$, where $X_j^a \in \{0,1\}$ denotes the failure indicator. We write $\eta_{\max} = \max_j \eta_j$ for the vulnerability of the weakest judge. The \emph{panel attack success rate} is $\mathrm{ASR}(\mathcal{P}, a) = \Pr\!\bigl(\sum_{j=1}^K X_j^a \geq t\bigr)$.

To quantify diversity, we define the \emph{effective independence} $K_{\mathrm{eff}}$ directly from pairwise mutual information (MI) among judges:
\begin{equation}
\label{eq:keff}
K_{\mathrm{eff}} = \frac{1}{K}\sum_{i=1}^{K} \Bigl[1 + \sum_{j \neq i} \exp\!\bigl(-2 \cdot \mathrm{MI}(i,j)\bigr)\Bigr].
\end{equation}
This formulation computes effective independence from pairwise MI estimates without matrix decomposition, and is more stable for small panels ($K{=}3$). It ranges from $K_{\mathrm{eff}} \approx K$ when judges are nearly independent ($\mathrm{MI} \to 0$) to $K_{\mathrm{eff}} \approx 1$ when judges are highly correlated ($\mathrm{MI} \to \infty$). Motivated by information-theoretic redundancy reduction, one can informally expect joint vulnerability to scale as $\eta_{\mathrm{joint}} \sim K_{\mathrm{eff}} \cdot \eta_{\max}$: independent channels multiply failure probabilities, so fewer effective channels (lower $K_{\mathrm{eff}}$) should reduce panel vulnerability. This motivating relationship assumes non-adaptive faults and independent channels; it serves as intuition rather than a formal bound.

\begin{definition}[Adaptive Adversary]
\label{def:adversary}
A \emph{full-knowledge (oracle) adaptive adversary} has complete knowledge of the panel composition $\mathcal{P}$, the per-judge vulnerability profiles $\{\eta_j(\cdot)\}_{j=1}^K$, and the inter-judge correlation structure. It selects the attack $a^* = \arg\max_{a \in \mathcal{A}} \mathrm{ASR}(\mathcal{P}, a)$ to maximize the panel ASR, yielding $\mathrm{ASR}^*(\mathcal{P}) = \sup_{a \in \mathcal{A}} \mathrm{ASR}(\mathcal{P}, a)$. This oracle model represents an \emph{upper bound} on adversarial capability; realistic adversaries with partial knowledge of panel composition would achieve lower ASR.
\end{definition}

This departs from BFT models~\cite{lamport1982byzantine,castro1999practical}, which tolerate $f < n/3$ faulty nodes but do not model adversaries that strategically target system structure. An adaptive adversary concentrates on the weakest link~\cite{schneier2000secrets}, suggesting a \emph{reversal}: under random faults, higher $K_{\mathrm{eff}}$ reduces joint failure probability, but under adaptive adversaries, diverse judges may present a wider attack surface.

\begin{proposition}[Weakest-Link Monotonicity; formal statement and proof in Appendix~\ref{app:proof}]
\label{thm:monotonicity}
Replacing any panel member with a pointwise more vulnerable judge can only increase $\mathrm{ASR}^*(\mathcal{P})$, for any adversary including adaptive ones. The stochastic dominance condition holds for 58\% of judge pairs (61/105); non-dominance concentrates among within-tier pairs (72.1\% non-dominant, 31/43) versus cross-tier pairs (21.0\%, 13/62), reflecting that capability-similar judges lack uniform ordering.
\end{proposition}

The proposition predicts $\beta_2 > 0$ in Equation~\ref{eq:regression}; the reversal pattern predicts positive $\beta_1$ under adversarial conditions. The relative importance of $\eta_{\max}$ versus $K_{\mathrm{eff}}$ depends on $K$: at small $K$, one weak judge flips the majority; at larger $K$, the adversary must compromise multiple judges (\S\ref{sec:experiments}).

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/fig_aggregation_r2_heatmap.pdf}
\caption{Predictability ($R^2$) across aggregation methods and panel sizes. Threshold voting is most predictable ($R^2{=}0.745$ at $K{=}3$); Bayesian calibration nearly neutralizes panel composition effects ($R^2{\leq}0.17$). All methods show declining $R^2$ from $K{=}3$ to $K{=}5$.}
\label{fig:aggregation_heatmap}
\end{figure}

\begin{figure*}[t]
\centering
\includegraphics[width=\textwidth]{figures/fig_per_model_asr.pdf}
\caption{Per-model ASR across six attack types (MMLU). Frontier models show near-zero vulnerability under most attacks; lightweight models exhibit heterogeneous weaknesses that drive the weakest-link effect.}
\label{fig:per_model_asr_main}
\end{figure*}

\begin{table}[t]
\centering
\small
\resizebox{\columnwidth}{!}{%
\begin{tabular}{lllccc}
\toprule
\textbf{Model} & \textbf{Family} & \textbf{Tier} & \textbf{Deploy} & \textbf{MMLU} & \textbf{ARC} \\
\midrule
gpt-5.5              & OpenAI    & frontier    & API   & .957 & .983 \\
gemini-3.1-pro-preview & Google  & frontier    & API   & .955 & .987 \\
claude-opus-4-6       & Anthropic & frontier   & API   & .890 & .987 \\
gemini-3.5-flash      & Google    & frontier   & API   & .968 & 1.00$^\dagger$ \\
\addlinespace
gpt-4.1               & OpenAI    & mid-tier   & API   & .837 & .967 \\
claude-sonnet-4-6     & Anthropic & mid-tier   & API   & .810 & .953 \\
\addlinespace
gpt-4.1-mini          & OpenAI    & lightweight & API  & .800 & .963 \\
gpt-4.1-nano          & OpenAI    & lightweight & API  & .633 & .853 \\
claude-3-haiku        & Anthropic & lightweight & API  & .767 & .450 \\
mistral-large (123B)  & Mistral   & lightweight & local & .537 & .533 \\
llama3.1-70b          & Llama     & lightweight & local & .523 & .520 \\
llama3.1-8b           & Llama     & lightweight & local & .543 & .320 \\
qwen2.5-72b           & Qwen      & lightweight & local & .333 & .410 \\
qwen2.5-32b           & Qwen      & lightweight & local & .373 & .450 \\
qwen2.5-14b           & Qwen      & lightweight & local & .253 & .240 \\
\bottomrule
\end{tabular}}
\caption{Judge models used in the study (clean accuracy on 300-item samples). API models accessed via OpenRouter (May 2026 snapshots); local models served with vLLM + AWQ INT4 quantization. $^\dagger$\,gemini-3.5-flash achieves perfect ARC accuracy but with 26.3\% format error rate. Tier assignment follows provider capability classification (frontier $>$85\% clean accuracy on both benchmarks, mid-tier 80--85\%, lightweight ${\leq}$80\% or quantized); all six local AWQ INT4 models fall into lightweight, where quantization-induced accuracy reduction conflates genuine capability limitations with quantization damage (\S\ref{sec:analysis}).}
\label{tab:models}
\end{table}

\section{Results}
\label{sec:results}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/fig_regime_transition.pdf}
\caption{Predictor shift across panel sizes. $\eta_{\max}$ significance (orange) drops from 5/12 to 0--1/12, while $K_{\mathrm{eff}}$ (blue) remains consistently high (7--8/12). Shaded region: $K^* \in (3, 5)$. Bootstrap: $B{=}9999$, Rademacher, max-$p$, BH FDR $\alpha{=}0.05$.}
\label{fig:regime_transition}
\end{figure}

\subsection{Weakest-Link Dominance at \texorpdfstring{$K{=}3$}{K=3}}
\label{sec:dominance}

Table~\ref{tab:dominance} reports the log-log OLS regression (Equation~\ref{eq:regression}) for all 12 conditions across the 455 panels ($K{=}3$, 15 judges from Table~\ref{tab:models}).

Under OLS, $K_{\mathrm{eff}}$ is FDR-significant in all 12/12 conditions (positive in 10, negative in 2 position-bias conditions). $\eta_{\max}$ is significant in 10/12 (exceptions: MMLU $\times$ score manipulation and ARC $\times$ position bias), consistent with Proposition~\ref{thm:monotonicity}. Dominance analysis yields 10 co-dominant, 2 $K_{\mathrm{eff}}$-dominant, and zero $\eta_{\max}$-dominant conditions. However, the $r = 0.70$ $K_{\mathrm{eff}}$--$\eta_{\max}$ correlation raises confound concerns, and OLS ignores the non-independence of the 455 panels (Appendix~\ref{app:keff_dist}).

Figure~\ref{fig:robustness} compares OLS against three corrections: both predictors attenuate under bootstrap ($\eta_{\max}$ 5/12, $K_{\mathrm{eff}}$ 8/12), with clustered SE widest ($K_{\mathrm{eff}}$ 0/12). Crossed random-effects analysis confirms $K_{\mathrm{eff}}$ significance at $K{\geq}5$ (Appendix~\ref{app:crossed_re}).

\begin{table}[t]
\centering
\small
\begin{tabular}{lcc}
\toprule
\textbf{Method} & $\boldsymbol{\eta_{\max}}$ \textbf{sig} & $\boldsymbol{K_{\mathrm{eff}}}$ \textbf{sig} \\
\midrule
OLS                    & 10/12 & 12/12 \\
Clustered SE           & 4/12  & 0/12  \\
Mixed effects          & 7/12  & 3/12  \\
Wild bootstrap         & 5/12  & 8/12  \\
Frac.\ logit (clust.)  & 8/12  & 10/12 \\
\bottomrule
\end{tabular}
\caption{Inference method sensitivity at $K{=}3$ (455 panels, 12 conditions). $K_{\mathrm{eff}}$ significance ranges from 0/12 (clustered SE) to 12/12 (OLS); positive direction is preserved in 10/12 conditions across all methods.}
\label{tab:method_comparison}
\end{table}

Power analysis yields MDE $\beta_{\mathrm{std}} = 0.14$ at 80\% power (Appendix~\ref{app:power_analysis}); positive coefficient direction (10/12) is preserved across all methods.

\subsection{The Diminishing Weakest Link Across Panel Sizes}
\label{sec:cross_k}

The $K{=}3$ pattern is method-sensitive (Table~\ref{tab:method_comparison}), contrasting with $K{\geq}5$ where $K_{\mathrm{eff}}$'s dominance is consistent (bootstrap 8/12; fractional logit 11/12). We repeat the bootstrap at $K \in \{3, 5, 7\}$ with max-$p$ correction.

Meta-analytic pooling \citep{dersimonian1986meta} quantifies trajectories independent of significance thresholds. $\eta_{\max}$'s pooled $\hat{\beta}_{\mathrm{std}}$ declines monotonically: $0.243$ [$0.163, 0.323$] at $K{=}3$, $0.091$ [$-0.031, 0.212$] at $K{=}5$, $0.086$ [$-0.039, 0.211$] at $K{=}7$; CI crosses zero at $K{\geq}5$. $K_{\mathrm{eff}}$'s pooled coefficient remains positive ($0.286$--$0.353$, CI excluding zero; Appendix~\ref{app:meta_analytic_details}). Figure~\ref{fig:regime_transition} shows significance counts; per-condition effect sizes with 95\% CIs are in Figure~\ref{fig:forest_plot} (Appendix~\ref{app:effect_size_forest}). The $\eta_{\max}$ decline holds under both $K_{\mathrm{eff}}$ and $\kappa$-diversity.


\subsection{Random vs.\ Adaptive Fault Contrast}
\label{sec:rf_contrast}

Random faults yield $R^2 = 0.730$ [$0.718, 0.745$]; adaptive attack reduces predictability ($R^2{=}0.285$ at $K{=}5$) but $K_{\mathrm{eff}}$ retains power (7/12). The positive $K_{\mathrm{eff}}$ coefficient under adaptive attack contrasts with the Condorcet Jury Theorem \citep{condorcet1785essai}: under adversarial manipulation, independent judges present distinct attack surfaces rather than redundant defenses \citep{goodfellow2015adversarial,kariyappa2019improving}.

\subsection{Positive Direction Across Attack Types}
\label{sec:gam_taxonomy}

GAM bootstrap confirms positive $K_{\mathrm{eff}}$ direction in 10 of 12 conditions (88.9--100\% positive rate; Figure~\ref{fig:gam_split}), with no magnitude difference between targeted and shared-bias attacks (Kruskal--Wallis $p{=}0.200$, $0.423$).

\paragraph{Position Bias Exception.}
Position bias stands apart: $K_{\mathrm{eff}}$'s coefficient is negative in both MMLU and ARC ($\hat{\beta}_{\mathrm{std}} = -0.334, -0.372$), indicating that diverse panels are \emph{less} susceptible to position bias. Position bias is a shared vulnerability---all judges exhibit the same directional preference---so independent judges provide genuine redundancy against this correlated failure mode, consistent with the Condorcet intuition. The two regimes (10 positive, 2 negative) thus align with the targeted-vs-shared attack taxonomy: targeted attacks exploit weak links (positive $K_{\mathrm{eff}}$), while shared-bias attacks are diluted by diversity (negative $K_{\mathrm{eff}}$).

\subsection{Aggregation Rules and the Diversity Channel}
\label{sec:aggregation}

Table~\ref{tab:aggregation} reports regression results for four aggregation methods across all 12 conditions.

\begin{table}[t]
\centering
\small
\begin{tabular}{lcccc}
\toprule
\textbf{Method} & \textbf{$\eta_{\max}$ sig} & \textbf{$K_{\mathrm{eff}}$ sig} & \textbf{$K_{\mathrm{eff}}$ $\beta$ dir.} & \textbf{$R^2$} \\
\midrule
Threshold       & 12/12 & 9/12  & 8+/1$-$   & 0.745 \\
Majority        & 10/12 & 12/12 & 10+/2$-$  & 0.349 \\
Weighted        & 9/12  & 12/12 & 10+/2$-$  & 0.336 \\
Bayesian        & 8/12  & 6/12  & 5+/1$-$   & 0.136 \\
\bottomrule
\end{tabular}
\caption{Aggregation method comparison ($K{=}3$, 15 models, 455 panels, OLS log-log). Significance counts are FDR-corrected across 12 conditions. $R^2$ is the mean across conditions. Table~\ref{tab:dominance} uses per-condition FDR; this table uses pooled FDR across conditions.}
\label{tab:aggregation}
\end{table}


Predictability ranges from threshold ($R^2{=}0.745$) to Bayesian ($R^2{=}0.136$), implying panel composition is almost unpredictive under calibrated aggregation. Bayesian calibration attenuates $K_{\mathrm{eff}}$ (5+/1$-$) but $\eta_{\max}$ persists (8/12). At $K{=}5$ all methods converge (7/12; Appendix~\ref{app:aggregation_k5}); at $K{=}7$ Bayesian neutralization returns (Appendix~\ref{app:aggregation_k7}).

\paragraph{Fractional Logit Robustness.}
Fractional logit \citep{papke1996econometric} with clustered SE shows consistent positive association: $K_{\mathrm{eff}}$ significance is 10--11/12 across all panel sizes ($K{=}3,5,7$), with 98.6\% directional concordance with OLS (71/72; Appendix~\ref{app:robustness_checks}).

